// Negative getter availability never authorizes a new round publication.
function publicationOffer(v){if(v?.phase!=='started')return null;if(v.reason_code==='FATO_PENDING'&&v.current_event)return {operation:v.current_event.operation_kind==='close'?'terminal':'fato',event:v.current_event.event_id};if(v.reason_code==='READY'&&v.window?.state==='private'&&v.window.publication_id===null)return {operation:'round',window:v.window.window_id,revision:v.window.preparation_revision};return null;}

const controlOps={phase:{rpc:'mission_factory_quest_human_phase_action_v1',keys:['p_session','p_expected_version','p_action','p_decision_key','p_request']},fato:{rpc:'mission_factory_quest_human_fato_publish_v1',keys:['p_session','p_event','p_body','p_request']},terminal:{rpc:'mission_factory_quest_human_terminal_publish_v1',keys:['p_session','p_event','p_body','p_request']},consume:{rpc:'mission_factory_quest_human_d100_consume_v1',keys:['p_session','p_receipt','p_source_sha256']},round:{rpc:'mission_factory_quest_human_round_publish_v1',keys:['p_session','p_window','p_body','p_expected_revision','p_request']}};
