 async function consumeD100(receiptId){const t=context(),v=await readRuntime();check(t);const r=v.d100_receipts.find(x=>x.receipt_id===receiptId&&!x.consumed);if(!v.can.consume_d100||!r)fail('Ricevuta d100 non disponibile.');await command('consume',{p_session:v.native_session_id,p_receipt:r.receipt_id,p_source_sha256:r.source_sha256});check(t);}
