export function mountHumanQuestParticipant(root,{client,api,identity=()=>null,isCurrent=()=>true,onScene=()=>{}}={}){let ep=null,view=null,generation=0,busy=false,disposed=false,message='Apri la tua puntata Human.';const current=()=>!disposed&&isCurrent()&&identity();const snapshot=()=>({generation,ep,actor:identity()});function check(t){if(!current()||t.generation!==generation||t.ep!==ep||t.actor!==identity())fail('Accesso o puntata cambiati: richieste conservate.');}async function auth(t){const r=await client.auth.getUser();check(t);if(r.error||r.data?.user?.id!==t.actor)fail('Accesso normale non confermato.');}async function readState(){const t=snapshot();await auth(t);const r=await client.rpc('mission_factory_quest_participant_state_v1',{p_episode:ep});check(t);if(r.error)throw r.error;view=humanParticipant(r.data,ep);return clone(view);}async function run(f){if(busy)fail('Comando personale in corso.');busy=true;draw();try{await f();}catch(e){message=e.message||'Richiesta non completata.';}finally{busy=false;if(current())draw();}}function btn(text,f,disabled=false){const x=document.createElement('button');x.type='button';x.textContent=text;x.disabled=busy||disabled;x.onclick=()=>{void run(f);};return x;}function paragraph(text){const p=document.createElement('p');p.textContent=text;return p;}async function enroll(op){const t=snapshot();const v=await readState();check(t);if(!v.actions[op])fail('Azione personale non offerta dal server.');const j=api.journal(ep);if(j.pending)fail('Recupera la richiesta originale.');const p={p_episode:ep,p_operation:op,p_ready:op==='ready'?!v.ready:null,p_expected_version:op==='join'?null:v.enrollment_control_version,p_request:crypto.randomUUID()};await api.send(ep,'enrollment',p);check(t);await readState();check(t);message='Iscrizione confermata dal server.';}async function scene(){const t=snapshot(),v=await readState();check(t);if(v.phase!=='started'||v.enrollment_state!=='joined'||v.present_now!==true)fail('Ingresso personale non disponibile.');await onScene({schema_version:'quest-human-participant-scene-link/1',episode:ep,session:v.native_session_id,character:v.character_id,location:STAFF_LOCATION});check(t);}function draw(){root.replaceChildren();root.append(paragraph(message));if(!ep)return;root.append(btn('Rileggi il mio stato',readState));const j=api.journal(ep);if(j.pending){root.append(paragraph('UUID personale conservata: '+j.pending.params.p_request),btn('Rileggi ricevuta personale',async()=>{const t=snapshot();await api.recover(ep);check(t);await readState();}),btn('Ripeti stessa richiesta personale',async()=>{const t=snapshot(),p=clone(api.journal(ep).pending);if(!p||p.operation!=='enrollment')fail('Richiesta personale non identificata.');await api.send(ep,p.operation,p.params,{replay:true});check(t);await readState();}));return;}if(!view)return;root.append(paragraph('Stato '+view.phase+' · '+(view.ready?'pronto':'non pronto')),btn('Partecipa',()=>enroll('join'),!view.actions.join),btn('Ritira iscrizione',()=>enroll('withdraw'),!view.actions.withdraw),btn(view.ready?'Non sono pronto':'Sono pronto',()=>enroll('ready'),!view.actions.ready),btn('Entra nella scena e nei pannelli',scene,view.phase!=='started'||view.present_now!==true));if(view.terminal)root.append(paragraph('Conclusione '+view.terminal.outcome+'. Premi Staff separati; nessuna progressione reale in questa prova.'));}async function openEpisode(id){if(busy||!UUID.test(id))fail('Puntata non valida o richiesta personale in corso.');generation++;ep=id;view=null;await run(readState);}draw();return{openEpisode,suspend(){generation++;view=null;},dispose(){disposed=true;generation++;api.dispose?.();root.replaceChildren();}};}

export function createPreparedHumanRegiaOptin({client,identity=()=>null,isCurrent=()=>true,storage=globalThis.localStorage}={}){let disposed=false;const current=()=>!disposed&&isCurrent()&&identity();const key=(actor,sid)=>'quest-human-prepared-optin/1/'+actor+'/'+sid;async function auth(actor){const r=await client.auth.getUser();if(!current()||identity()!==actor||r.error||r.data?.user?.id!==actor)fail('Accesso Master cambiato: prenotazione conservata.');}async function call(name,p,actor){await auth(actor);const r=await client.rpc(name,p);await auth(actor);if(r.error)throw r.error;return r.data;}function prepare(q){if(!exact(q,prepareKeys)||q.schema_version!=='quest-human-episode-prepare/1'||q.state!=='prepared'||q.location_id!==STAFF_LOCATION||q.control_version!==1||!UUID.test(q.request_key)||!UUID.test(q.native_session_id)||!SHA.test(q.source_sha256)||!SHA.test(q.roster_snapshot_sha256))fail('Preparazione Native non qualificata per Regia.');return clone(q);}function receipt(v,p,q,actor){if(!exact(v,['schema_version','native_session_id','request_key','status','assigned_master','source_sha256','prepare_request_key','expected_control_version','roster_snapshot_sha256','identity_sha256'])||v.schema_version!=='quest-human-regia-optin/1'||v.status!=='reserved'||v.native_session_id!==p.p_session||v.request_key!==p.p_request||v.assigned_master!==actor||v.source_sha256!==p.p_expected_source_sha256||v.prepare_request_key!==q.request_key||v.expected_control_version!==p.p_expected_control_version||v.roster_snapshot_sha256!==q.roster_snapshot_sha256||!SHA.test(v.identity_sha256))fail('Prenotazione Regia non confermata.');return clone(v);}function read(q,actor){let j;try{j=JSON.parse(storage.getItem(key(actor,q.native_session_id))||'null');}catch{fail('Journal Regia non leggibile.');}if(!j)return null;if(!exact(j,['schema_version','actor','prepare_request_key','params','receipt'])||j.schema_version!=='quest-human-prepared-optin/1'||j.actor!==actor||j.prepare_request_key!==q.request_key||!exact(j.params,['p_session','p_expected_control_version','p_expected_source_sha256','p_request'])||j.params.p_session!==q.native_session_id||j.params.p_expected_control_version!==q.control_version||j.params.p_expected_source_sha256!==q.source_sha256||!UUID.test(j.params.p_request)||j.params.p_request===q.request_key)fail('Journal Regia diverso dalla preparazione.');if(j.receipt)receipt(j.receipt,j.params,q,actor);return j;}function store(j){const k=key(j.actor,j.params.p_session),text=JSON.stringify(j);storage.setItem(k,text);if(storage.getItem(k)!==text)fail('Prenotazione non persistita: nessun invio.');}async function recover(value){const q=prepare(value),actor=identity();await auth(actor);const j=read(q,actor);if(!j)return null;const v=await call('mission_factory_quest_human_regia_optin_receipt_v1',{p_session:q.native_session_id,p_request:j.params.p_request},actor);if(!exact(v,['schema_version','native_session_id','request_key','status','receipt'])||v.schema_version!=='quest-human-regia-optin-recovery/1'||v.native_session_id!==q.native_session_id||v.request_key!==j.params.p_request||!['reserved','not_found'].includes(v.status)||v.status==='not_found'&&v.receipt!==null)fail('Recupero Regia non compatibile.');const latest=read(q,actor);if(JSON.stringify(latest.params)!==JSON.stringify(j.params))fail('Puntatore Regia cambiato: conserva UUID.');if(v.status==='reserved'){latest.receipt=receipt(v.receipt,j.params,q,actor);store(latest);return clone(latest.receipt);}return null;}async function reserve(value,authorize,{replay=false}={}){const q=prepare(value),actor=identity();await auth(actor);let j=read(q,actor);if(j){const r=await recover(q);if(r)return r;if(!replay)fail('Prenotazione originale da recuperare o ripetere.');}else if(replay)fail('Nessuna prenotazione originale.');if(typeof authorize!=='function')fail('Rilettura della preparazione necessaria.');await authorize(clone(q));await auth(actor);const r=runDTO(await call('mission_factory_quest_run_state_v1',{p_request:q.request_key},actor),q.request_key);if(r.state!=='prepared'||r.operation!=='prepare'||(!exact(r.receipt,prepareKeys)||prepareKeys.some(k=>r.receipt[k]!==q[k])))fail('Preparazione cambiata: nessuna nuova prenotazione.');await authorize(clone(q));await auth(actor);if(!j){const request=crypto.randomUUID();if(request===q.request_key)fail('UUID non distinta.');j={schema_version:'quest-human-prepared-optin/1',actor,prepare_request_key:q.request_key,params:{p_session:q.native_session_id,p_expected_control_version:q.control_version,p_expected_source_sha256:q.source_sha256,p_request:request},receipt:null};store(j);}const original=clone(j.params);await auth(actor);const latest=read(q,actor);if(JSON.stringify(latest.params)!==JSON.stringify(original))fail('Prenotazione cambiata prima dell’invio.');const v=receipt(await call('mission_factory_quest_human_regia_optin_v1',original,actor),original,q,actor);j=read(q,actor);if(JSON.stringify(j.params)!==JSON.stringify(original))fail('Prenotazione committata: recupera UUID originale.');j.receipt=v;store(j);return clone(v);}return{reserve,recover,repeat:(q,authorize)=>reserve(q,authorize,{replay:true}),journal:q=>{const p=prepare(q);return clone(read(p,identity()));},dispose(){disposed=true;}};}
